export default {"html":"<p data-line=\"0\" class=\"code-line\">Ionic Angular Standalone created two import sources. For example, <code>ModalController</code> can be imported like this:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"2\"><span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { IonToolbar } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@ionic/angular'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { IonToolbar } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@ionic/angular/standalone'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"7\" class=\"code-line\">The former is for components available only when you import IonicModule; the latter imports components as Standalone Components. When I add imports by hand, I know the project is Standalone-ready, so I do not make mistakes—but IDE suggestions make it easy to pick the wrong path.</p>\n<p data-line=\"9\" class=\"code-line\"><img src=\"/images/d6b6c32a1f9d84/ide.png\" alt=\"\" class=\"md-img\" loading=\"lazy\"></p>\n<p data-line=\"11\" class=\"code-line\">Also, if I import <code>IonToolbar</code> incorrectly, the IDE reports an error, which is fine. But OverlayController types such as <code>ModalController</code> fail at runtime without an IDE error, so it is hard to notice unless I run the app. So I created an ESLint rule that errors when you import from <code>@ionic/angular</code>. Set it up after migrating Ionic Angular to Standalone.</p>\n<h2 id=\"usage\" data-line=\"13\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#usage\" aria-hidden=\"true\"></a> Usage</h2>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"15\"><span class=\"line\"><span style=\"color:#B392F0\">npm</span><span style=\"color:#9ECBFF\"> install</span><span style=\"color:#9ECBFF\"> @rdlabo/eslint-plugin-rules</span><span style=\"color:#79B8FF\"> --save-dev</span></span>\n<span class=\"line\"></span></code></pre></div><div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"19\"><span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#FDAEB7;font-style:italic\">   ...</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#FDAEB7;font-style:italic\"></span><span style=\"color:#79B8FF\">   \"plugins\"</span><span style=\"color:#E1E4E8\">: [</span><span style=\"color:#9ECBFF\">\"@rdlabo/rules\"</span><span style=\"color:#E1E4E8\">],</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#79B8FF\">   \"overrides\"</span><span style=\"color:#E1E4E8\">: [</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">     {</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#79B8FF\">       \"files\"</span><span style=\"color:#E1E4E8\">: [</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#9ECBFF\">         \"*.ts\"</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">       ],</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#FDAEB7;font-style:italic\">     ...</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#79B8FF\">       \"rules\"</span><span style=\"color:#E1E4E8\">: {</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span style=\"color:#FDAEB7;font-style:italic\"></span><span style=\"color:#79B8FF\">         \"@rdlabo/rules/deny-import-from-ionic-module\"</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">\"error\"</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">       }</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">     },</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\">   ]</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span style=\"color:#E1E4E8\"> }</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"when-an-error-appears\" data-line=\"37\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#when-an-error-appears\" aria-hidden=\"true\"></a> When an error appears</h2>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"39\"><span class=\"line\"><span style=\"color:#F97583\">&gt;</span><span style=\"color:#E1E4E8\"> ng lint</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#B392F0\">Linting</span><span style=\"color:#9ECBFF\"> \"app\"...</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#B392F0\">/home/runner/work/winecode/winecode/app/src/app/list/modals/thread-over-view/thread-over-view.page.ts</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">Lint</span><span style=\"color:#9ECBFF\"> errors</span><span style=\"color:#9ECBFF\"> found</span><span style=\"color:#9ECBFF\"> in</span><span style=\"color:#9ECBFF\"> the</span><span style=\"color:#9ECBFF\"> listed</span><span style=\"color:#9ECBFF\"> files.</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">Error:</span><span style=\"color:#9ECBFF\">   1:1</span><span style=\"color:#9ECBFF\">  error</span><span style=\"color:#9ECBFF\">  You</span><span style=\"color:#9ECBFF\"> must</span><span style=\"color:#9ECBFF\"> import</span><span style=\"color:#9ECBFF\"> from</span><span style=\"color:#9ECBFF\"> @ionic/angular/standalone</span><span style=\"color:#9ECBFF\"> instead</span><span style=\"color:#9ECBFF\"> of</span><span style=\"color:#9ECBFF\"> @ionic/angular</span><span style=\"color:#9ECBFF\">  @rdlabo/rules/deny-import-from-ionic-module</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#B392F0\">✖</span><span style=\"color:#79B8FF\"> 1</span><span style=\"color:#9ECBFF\"> problem</span><span style=\"color:#E1E4E8\"> (1 </span><span style=\"color:#9ECBFF\">error,</span><span style=\"color:#79B8FF\"> 0</span><span style=\"color:#9ECBFF\"> warnings</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  1</span><span style=\"color:#9ECBFF\"> error</span><span style=\"color:#9ECBFF\"> and</span><span style=\"color:#79B8FF\"> 0</span><span style=\"color:#9ECBFF\"> warnings</span><span style=\"color:#9ECBFF\"> potentially</span><span style=\"color:#9ECBFF\"> fixable</span><span style=\"color:#9ECBFF\"> with</span><span style=\"color:#9ECBFF\"> the</span><span style=\"color:#9ECBFF\"> `</span><span style=\"color:#B392F0\">--fix</span><span style=\"color:#9ECBFF\">`</span><span style=\"color:#B392F0\"> option.</span></span>\n<span class=\"line\"></span></code></pre></div><h3 id=\"summary\" data-line=\"54\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h3>\n<p data-line=\"56\" class=\"code-line\">It supports auto-fix as well, so I hope you will use it to avoid mistakes. See you next time.</p>\n","headings":[{"id":"usage","text":"Usage","level":2},{"id":"when-an-error-appears","text":"When an error appears","level":2},{"id":"summary","text":"Summary","level":3}]} as const;
